    var statusHistory = new List<WorkerBridgeStatus>();
    GmWorkerExecutionAuthority? executionAuthority = null;
    var cleanupDeferred = false;
    WorkerBridgeStatus Track(
        WorkerBridgeState state,
        bool ready,
        string? lastError = null,
        int? processId = null)
    {
